Method.Implementation:
set tSC = $$$OK
NEW $NAMESPACE
set $NAMESPACE = "ITFCOMMON"

&sql(select ID into :nmId from ITFCOMMON_SrcCtrl.Namespaces  where NameSpace = :nmSp)

if (SQLCODE = 0)
{
   &sql(INSERT INTO ITFCOMMON_SrcCtrl.Component (ComponentName, NameSpace) values ( :itemNm, :nmId ))
   set tSC = $$$ERROR("Insert failed. SQLCODE: " _ SQLCODE)
}
else 
{
	 set tSC = $$$ERROR("Selection of Namespace ID failed for" _ nmSp _ ". SQLCODE: " _ SQLCODE)
}
return tSC

	Do ##class(ITFCOMMON.Utility).WriteToFile("GetComponentId")
    &sql(Select c.ID INTO :compId from ITFCOMMON_SrcCtrl.Component c,  ITFCOMMON_SrcCtrl.Namespaces n where n.ID = c.NameSpace AND c.ComponentName = :compNm  AND n.NameSpace = :nmSp)
    IF (SQLCODE '= 0) {
	    set tSC = ..InsertComponent(compNm, nmSp)
	    if $$$ISOK(tSC)
	    {
		    set SQLCODE = 0
		    &sql(Select ID INTO :compId from ITFCOMMON_SrcCtrl.Component  where ComponentName = :compNm  )
	    }
	    if ( (SQLCODE '= 0) || ($$$ISERR(tSC)) )
	    {
	    	set fault=..MakeFault($$$FAULTServer, "SQL error", "Could not get Component Id for " _ compNm _ " from ITFCOMMON_SrcCtrl.Component")
	   		Do ..ReturnFault(fault)
	   		QUIT
	    }

    }
    Do ##class(ITFCOMMON.Utility).WriteToFile("ComponentId: " _ compId) 
    return compId

NEW $NAMESPACE set $NAMESPACE = "ITFCOMMON" Do ##class(ITFCOMMON.Utility).WriteToFile("In UpdateClassItem") set compId = ..GetComponentId(componentNm, nmSp)
set envId = ..GetEnvironmentId(env) set dt = $ZDATETIME($ZTIMESTAMP,3, 1) &sql(INSERT INTO ITFCOMMON_SrcCtrl.ClassItem (ClassName, ComponentName, Environment, ClassExportFile, ClassExportFileVersion, ClassExportFileInformation, ImportDate ) values (:clNm, :compId, :envId, :DeploymentFile, :fileVersion, :fileInfo, :dt ) ) if SQLCODE = 0 { Do ##class(ITFCOMMON.Utility).WriteToFile("Insert Done") return $$$OK } else { set fault=..MakeFault($$$FAULTServer, "SQL error", "Insert to ComponentImpl failed " _ $SYSTEM.SQL.SQLCODE(SQLCODE)) Do ..ReturnFault(fault) QUIT
}
